import FlexSearch from "flexsearch";

export type SearchContent = {
	title: string;
	content: string;
	description: string;
	href: string;
};

export type SearchResult = SearchContent & {
	snippet?: string;
	highlights?: string[];
	category?: string;
};

let titleIndex: FlexSearch.Index;
let contentIndex: FlexSearch.Index;
let content: SearchContent[] = [];

export function createContentIndex(data: SearchContent[]) {
	titleIndex = new FlexSearch.Index({
		tokenize: "forward",
		resolution: 9,
	});

	contentIndex = new FlexSearch.Index({
		tokenize: "forward",
		resolution: 5,
	});

	data.forEach((item, i) => {
		titleIndex.add(i, item.title);
		contentIndex.add(i, `${item.content} ${item.description}`);
	});

	content = data;
}

function getContentSnippet(content: string, query: string, maxLength = 150): string {
	const words = query.toLowerCase().split(/\s+/);
	const contentLower = content.toLowerCase();

	let bestIndex = -1;

	for (const word of words) {
		const index = contentLower.indexOf(word);
		if (index !== -1 && (bestIndex === -1 || index < bestIndex)) {
			bestIndex = index;
		}
	}

	if (bestIndex === -1) {
		return content.slice(0, maxLength) + (content.length > maxLength ? "..." : "");
	}

	const start = Math.max(0, bestIndex - Math.floor(maxLength / 2));
	const end = Math.min(content.length, start + maxLength);
	const snippet = content.slice(start, end);

	return (start > 0 ? "..." : "") + snippet + (end < content.length ? "..." : "");
}

function highlightMatches(text: string, query: string): string {
	const words = query
		.toLowerCase()
		.split(/\s+/)
		.filter((w) => w.length > 1);
	let highlighted = text;

	for (const word of words) {
		const regex = new RegExp(`(${word})`, "gi");
		highlighted = highlighted.replace(regex, "<mark>$1</mark>");
	}

	return highlighted;
}

function categorizeResult(href: string): string {
	if (href.includes("/components/")) return "Components";
	if (href.includes("/utilities/")) return "Utilities";
	if (href.includes("/type-helpers/")) return "Type Helpers";
	return "Guides";
}

function fuzzyMatch(text: string, query: string): boolean {
	const textLower = text.toLowerCase();
	const queryLower = query.toLowerCase();
	if (textLower.includes(queryLower)) return true;

	let queryIndex = 0;
	for (let i = 0; i < textLower.length && queryIndex < queryLower.length; i++) {
		if (textLower[i] === queryLower[queryIndex]) {
			queryIndex++;
		}
	}
	return queryIndex === queryLower.length;
}

export function searchContentIndex(query: string): SearchResult[] {
	if (!query.trim()) return [];

	const titleResults = titleIndex.search(query, { limit: 20, suggest: true });
	const contentResults = contentIndex.search(query, { limit: 20, suggest: true });

	const resultMap = new Map<FlexSearch.Id, { score: number; source: string }>();

	for (const id of titleResults) {
		resultMap.set(id, { score: 10, source: "title" });
	}

	for (const id of contentResults) {
		const existing = resultMap.get(id);
		if (existing) {
			existing.score += 5;
		} else {
			resultMap.set(id, { score: 5, source: "content" });
		}
	}

	if (resultMap.size === 0) {
		content.forEach((item, idx) => {
			if (fuzzyMatch(item.title, query)) {
				resultMap.set(idx, { score: 8, source: "fuzzy-title" });
			} else if (fuzzyMatch(item.content, query) || fuzzyMatch(item.description, query)) {
				resultMap.set(idx, { score: 3, source: "fuzzy-content" });
			}
		});
	}

	const sortedResults = Array.from(resultMap.entries())
		.sort(([, a], [, b]) => b.score - a.score)
		.slice(0, 10);

	return sortedResults.map(([idx]) => {
		const item = content[idx as number];
		const snippet = getContentSnippet(item.content, query);
		return {
			...item,
			snippet: highlightMatches(snippet, query),
			highlights: query
				.toLowerCase()
				.split(/\s+/)
				.filter((w) => w.length > 1),
			category: categorizeResult(item.href),
		};
	});
}

import removeMd from "remove-markdown";
import { componentDocs, docs, typeHelperDocs, utilityDocs } from "$content/index.js";

function cleanContent(raw: string): string {
	let content = removeMd(raw, {
		replaceLinksWithURL: true,
		gfm: true,
		useImgAltText: true,
	});

	content = content.replace(/```[\s\S]*?```/g, "");
	content = content.replace(/`[^`]+`/g, "");
	content = content.replace(/\s+/g, " ").trim();
	content = content.replace(/\[([^\]]+)\]\([^)]+\)/g, "$1");
	content = content.replace(/#{1,6}\s*/g, "");
	content = content.replace(/\*{1,2}([^*]+)\*{1,2}/g, "$1");

	return content;
}

export function buildDocsIndex() {
	const components = componentDocs.map((doc) => {
		return {
			title: doc.title,
			content: cleanContent(doc.raw),
			description: doc.description,
			href: `/docs/components/${doc.slug}`,
		};
	});

	const utilities = utilityDocs.map((doc) => {
		return {
			title: doc.title,
			content: cleanContent(doc.raw),
			description: doc.description,
			href: `/docs/utilities/${doc.slug}`,
		};
	});

	const typeHelpers = typeHelperDocs.map((doc) => {
		return {
			title: doc.title,
			content: cleanContent(doc.raw),
			description: doc.description,
			href: `/docs/type-helpers/${doc.slug}`,
		};
	});

	const mainPages = docs.map((doc) => {
		return {
			title: doc.title,
			content: cleanContent(doc.raw),
			description: doc.description,
			href: `/docs/${doc.slug}`,
		};
	});

	return [...components, ...utilities, ...typeHelpers, ...mainPages];
}

